import React, { useState, useRef, useEffect } from "react";
import axios from "axios";

const API = "http://localhost:8000";

export default function Dashboard({ user, onLogout }) {
  const [activeTab, setActiveTab] = useState("upload");
  const [sessionId, setSessionId] = useState(null);
  const [bookName, setBookName] = useState("");
  const [uploading, setUploading] = useState(false);
  const [uploadProgress, setUploadProgress] = useState(0);
  const [uploadDone, setUploadDone] = useState(false);
  const [messages, setMessages] = useState([]);
  const [question, setQuestion] = useState("");
  const [asking, setAsking] = useState(false);
  const [totalSaved, setTotalSaved] = useState(0);
  const [totalTokens, setTotalTokens] = useState(0);
  const [dragOver, setDragOver] = useState(false);
  const fileRef = useRef();
  const chatRef = useRef();

  useEffect(() => {
    if (chatRef.current) {
      chatRef.current.scrollTop = chatRef.current.scrollHeight;
    }
  }, [messages]);

  const handleFile = async (file) => {
    if (!file || !file.name.endsWith(".pdf")) {
      alert("Please upload a PDF file only.");
      return;
    }
    setUploading(true);
    setUploadProgress(0);
    const formData = new FormData();
    formData.append("file", file);
    try {
      const res = await axios.post(`${API}/upload`, formData, {
        onUploadProgress: (e) => {
          setUploadProgress(Math.round((e.loaded / e.total) * 100));
        },
      });
      setSessionId(res.data.session_id);
      setBookName(file.name.replace(".pdf", ""));
      setUploadDone(true);
      setMessages([{
        role: "assistant",
        text: `📚 **${file.name}** has been processed successfully! I found **${res.data.chapters_found} chapters**. Ask me anything from this textbook!`,
        time: new Date().toLocaleTimeString(),
      }]);
      setActiveTab("chat");
    } catch {
      alert("Upload failed. Make sure backend is running.");
    }
    setUploading(false);
  };

  const handleDrop = (e) => {
    e.preventDefault();
    setDragOver(false);
    const file = e.dataTransfer.files[0];
    handleFile(file);
  };

  const askQuestion = async () => {
    if (!question.trim() || !sessionId) return;
    const q = question.trim();
    setQuestion("");
    setMessages(prev => [...prev, { role: "user", text: q, time: new Date().toLocaleTimeString() }]);
    setAsking(true);
    try {
      const res = await axios.post(`${API}/ask`, { session_id: sessionId, question: q });
      const stats = res.data.context_stats;
      setTotalSaved(prev => prev + stats.reduction_percent);
      setTotalTokens(prev => prev + res.data.tokens_used.total_tokens);
      setMessages(prev => [...prev, {
        role: "assistant",
        text: res.data.answer,
        time: new Date().toLocaleTimeString(),
        stats: {
          saved: stats.reduction_percent,
          chapters: stats.chapters_used,
          total: stats.total_chapters,
          tokens: res.data.tokens_used.total_tokens,
          refs: res.data.chapters_referenced,
        }
      }]);
    } catch {
      setMessages(prev => [...prev, { role: "assistant", text: "❌ Error getting answer. Please try again.", time: new Date().toLocaleTimeString() }]);
    }
    setAsking(false);
  };

  return (
    <div style={styles.container}>
      <div style={styles.bgGrid}></div>

      <aside style={styles.sidebar}>
        <div style={styles.sidebarLogo}>
          <div style={styles.sideLogoIcon}>
            <svg width="22" height="22" viewBox="0 0 32 32" fill="none">
              <path d="M16 2L28 8V16C28 22.627 22.627 29.254 16 30C9.373 29.254 4 22.627 4 16V8L16 2Z" fill="url(#grad2)"/>
              <path d="M11 16L14.5 19.5L21 13" stroke="white" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"/>
              <defs><linearGradient id="grad2" x1="4" y1="2" x2="28" y2="30" gradientUnits="userSpaceOnUse"><stop stopColor="#4f8ef7"/><stop offset="1" stopColor="#7c3aed"/></linearGradient></defs>
            </svg>
          </div>
          <span style={styles.sideLogoText} className="glow-text">VidyAI</span>
        </div>

        <nav style={styles.nav}>
          {[
            { id: "upload", icon: "📤", label: "Upload Book" },
            { id: "chat", icon: "💬", label: "Ask Tutor" },
            { id: "stats", icon: "📊", label: "Cost Savings" },
          ].map(tab => (
            <button
              key={tab.id}
              onClick={() => setActiveTab(tab.id)}
              style={{ ...styles.navBtn, ...(activeTab === tab.id ? styles.navBtnActive : {}) }}
            >
              <span style={styles.navIcon}>{tab.icon}</span>
              <span style={styles.navLabel}>{tab.label}</span>
              {activeTab === tab.id && <span style={styles.navIndicator}></span>}
            </button>
          ))}
        </nav>

        <div style={styles.sidebarBottom}>
          {uploadDone && (
            <div style={styles.activeBook}>
              <div style={styles.activeBookIcon}>📖</div>
              <div>
                <div style={styles.activeBookName}>{bookName}</div>
                <div style={styles.activeBookSub}>Active Textbook</div>
              </div>
            </div>
          )}
          <div style={styles.userCard}>
            <div style={styles.userAvatar}>{user.name[0]}</div>
            <div style={styles.userInfo}>
              <div style={styles.userName}>{user.name}</div>
              <div style={styles.userRole}>{user.role} · {user.class}</div>
            </div>
            <button onClick={onLogout} style={styles.logoutBtn} title="Logout">⏻</button>
          </div>
        </div>
      </aside>

      <main style={styles.main}>
        {activeTab === "upload" && (
          <div style={styles.content} className="animate-fadeInUp">
            <div style={styles.pageHeader}>
              <h1 style={styles.pageTitle}>Upload Textbook</h1>
              <p style={styles.pageSub}>Upload any state-board PDF textbook to get started</p>
            </div>

            <div
              style={{ ...styles.dropzone, ...(dragOver ? styles.dropzoneActive : {}) }}
              onDragOver={(e) => { e.preventDefault(); setDragOver(true); }}
              onDragLeave={() => setDragOver(false)}
              onDrop={handleDrop}
              onClick={() => fileRef.current.click()}
            >
              <input ref={fileRef} type="file" accept=".pdf" style={{ display: "none" }} onChange={e => handleFile(e.target.files[0])} />
              {uploading ? (
                <div style={styles.uploadingState}>
                  <div style={styles.progressRing}>
                    <svg width="80" height="80" viewBox="0 0 80 80">
                      <circle cx="40" cy="40" r="32" fill="none" stroke="var(--border)" strokeWidth="6"/>
                      <circle cx="40" cy="40" r="32" fill="none" stroke="url(#pg)" strokeWidth="6"
                        strokeDasharray={`${2 * Math.PI * 32}`}
                        strokeDashoffset={`${2 * Math.PI * 32 * (1 - uploadProgress / 100)}`}
                        strokeLinecap="round"
                        transform="rotate(-90 40 40)"
                        style={{ transition: "stroke-dashoffset 0.3s ease" }}
                      />
                      <defs><linearGradient id="pg" x1="0" y1="0" x2="1" y2="0"><stop stopColor="#4f8ef7"/><stop offset="1" stopColor="#7c3aed"/></linearGradient></defs>
                    </svg>
                    <span style={styles.progressText}>{uploadProgress}%</span>
                  </div>
                  <p style={styles.uploadingText}>Processing textbook...</p>
                  <p style={styles.uploadingSubText}>Extracting chapters & building index</p>
                </div>
              ) : (
                <div style={styles.dropzoneContent}>
                  <div style={styles.dropzoneIcon}>📄</div>
                  <h3 style={styles.dropzoneTitle}>Drop your PDF here</h3>
                  <p style={styles.dropzoneSub}>or click to browse files</p>
                  <div style={styles.dropzoneHint}>
                    <span className="badge badge-blue">PDF Only</span>
                    <span className="badge badge-green">Any Size</span>
                    <span className="badge badge-purple">State Board Ready</span>
                  </div>
                </div>
              )}
            </div>

            <div style={styles.infoGrid}>
              {[
                { icon: "⚡", title: "Context Pruning", desc: "Only relevant chapters sent to AI — saves 80%+ cost" },
                { icon: "🔒", title: "Local Processing", desc: "Embeddings built locally, no data leaves your device" },
                { icon: "📡", title: "Low Bandwidth", desc: "Minimal data transfer — works on 2G connections" },
              ].map((item, i) => (
                <div key={i} className="card" style={styles.infoCard}>
                  <div style={styles.infoIcon}>{item.icon}</div>
                  <h3 style={styles.infoTitle}>{item.title}</h3>
                  <p style={styles.infoDesc}>{item.desc}</p>
                </div>
              ))}
            </div>
          </div>
        )}

        {activeTab === "chat" && (
          <div style={styles.chatLayout} className="animate-fadeIn">
            <div style={styles.chatHeader}>
              <div>
                <h2 style={styles.chatTitle}>AI Tutor</h2>
                <p style={styles.chatSub}>{uploadDone ? `📖 ${bookName}` : "Upload a textbook first"}</p>
              </div>
              <div style={styles.chatBadges}>
                <span className="badge badge-green">● Live</span>
                <span className="badge badge-blue">⚡ Groq LLaMA3</span>
              </div>
            </div>

            <div ref={chatRef} style={styles.chatMessages}>
              {messages.length === 0 && (
                <div style={styles.emptyChat}>
                  <div style={styles.emptyChatIcon}>🎓</div>
                  <h3 style={styles.emptyChatTitle}>Upload a textbook to begin</h3>
                  <p style={styles.emptyChatSub}>Your AI tutor is ready to help you learn</p>
                </div>
              )}
              {messages.map((msg, i) => (
                <div key={i} style={{ ...styles.msgWrap, ...(msg.role === "user" ? styles.msgWrapUser : {}) }}>
                  {msg.role === "assistant" && (
                    <div style={styles.msgAvatar}>🤖</div>
                  )}
                  <div style={{ maxWidth: "75%" }}>
                    <div style={{ ...styles.msgBubble, ...(msg.role === "user" ? styles.msgBubbleUser : styles.msgBubbleBot) }}>
                      <p style={styles.msgText}>{msg.text}</p>
                    </div>
                    {msg.stats && (
                      <div style={styles.statsRow}>
                        <span style={styles.statChip}>✂️ {msg.stats.saved}% pruned</span>
                        <span style={styles.statChip}>📚 {msg.stats.chapters}/{msg.stats.total} chapters</span>
                        <span style={styles.statChip}>🔤 {msg.stats.tokens} tokens</span>
                      </div>
                    )}
                    <div style={styles.msgTime}>{msg.time}</div>
                  </div>
                  {msg.role === "user" && (
                    <div style={styles.msgAvatarUser}>{user.name[0]}</div>
                  )}
                </div>
              ))}
              {asking && (
                <div style={styles.msgWrap}>
                  <div style={styles.msgAvatar}>🤖</div>
                  <div style={styles.typingBubble}>
                    <span style={styles.dot}></span>
                    <span style={{ ...styles.dot, animationDelay: "0.2s" }}></span>
                    <span style={{ ...styles.dot, animationDelay: "0.4s" }}></span>
                  </div>
                </div>
              )}
            </div>

            <div style={styles.inputArea}>
              <input
                className="input-field"
                style={styles.chatInput}
                placeholder={uploadDone ? "Ask anything from your textbook..." : "Upload a textbook first..."}
                value={question}
                onChange={e => setQuestion(e.target.value)}
                onKeyDown={e => e.key === "Enter" && !e.shiftKey && askQuestion()}
                disabled={!uploadDone || asking}
              />
              <button
                className="btn-primary"
                onClick={askQuestion}
                disabled={!uploadDone || asking || !question.trim()}
                style={styles.sendBtn}
              >
                {asking ? <span className="loader"></span> : "Send →"}
              </button>
            </div>
          </div>
        )}

        {activeTab === "stats" && (
          <div style={styles.content} className="animate-fadeInUp">
            <div style={styles.pageHeader}>
              <h1 style={styles.pageTitle}>Cost Savings Dashboard</h1>
              <p style={styles.pageSub}>See how Context Pruning saves money vs baseline RAG</p>
            </div>

            <div style={styles.statsGrid}>
              {[
                { label: "Avg Context Reduction", value: messages.filter(m => m.stats).length > 0 ? `${Math.round(totalSaved / messages.filter(m => m.stats).length)}%` : "—", icon: "✂️", color: "#10b981" },
                { label: "Total Tokens Used", value: totalTokens || "—", icon: "🔤", color: "#4f8ef7" },
                { label: "Queries Made", value: messages.filter(m => m.role === "user").length, icon: "💬", color: "#7c3aed" },
                { label: "Est. Cost Saved", value: totalTokens ? `$${((totalTokens * 0.8 * 0.0001) / 1000).toFixed(4)}` : "—", icon: "💰", color: "#f59e0b" },
              ].map((s, i) => (
                <div key={i} className="card" style={styles.statCard}>
                  <div style={{ ...styles.statIcon, color: s.color }}>{s.icon}</div>
                  <div style={{ ...styles.statValue, color: s.color }}>{s.value}</div>
                  <div style={styles.statLabel}>{s.label}</div>
                </div>
              ))}
            </div>

            <div className="card" style={styles.comparisonCard}>
              <h3 style={styles.compTitle}>Baseline RAG vs Context Pruning</h3>
              <div style={styles.compGrid}>
                <div style={styles.compCol}>
                  <div style={styles.compHeader}>
                    <span style={styles.compBadgeRed}>❌ Baseline RAG</span>
                  </div>
                  {["Sends entire textbook every query", "~50,000 tokens per query", "High latency on slow networks", "Expensive for rural students", "Not viable on 2G"].map((t, i) => (
                    <div key={i} style={styles.compRow}>
                      <span style={{ color: "#ef4444" }}>✗</span> <span style={styles.compText}>{t}</span>
                    </div>
                  ))}
                </div>
                <div style={styles.compDivider}></div>
                <div style={styles.compCol}>
                  <div style={styles.compHeader}>
                    <span style={styles.compBadgeGreen}>✅ Context Pruning</span>
                  </div>
                  {["Sends only 2-3 relevant chapters", "~3,000 tokens per query", "Fast even on 2G networks", "80%+ cost reduction", "Built for rural India"].map((t, i) => (
                    <div key={i} style={styles.compRow}>
                      <span style={{ color: "#10b981" }}>✓</span> <span style={styles.compText}>{t}</span>
                    </div>
                  ))}
                </div>
              </div>
            </div>
          </div>
        )}
      </main>
    </div>
  );
}

const styles = {
  container: { display: "flex", minHeight: "100vh", background: "var(--bg-primary)", position: "relative" },
  bgGrid: { position: "fixed", inset: 0, backgroundImage: "linear-gradient(rgba(79,142,247,0.02) 1px, transparent 1px), linear-gradient(90deg, rgba(79,142,247,0.02) 1px, transparent 1px)", backgroundSize: "60px 60px", pointerEvents: "none" },
  sidebar: { width: "260px", flexShrink: 0, background: "var(--bg-secondary)", borderRight: "1px solid var(--border)", display: "flex", flexDirection: "column", padding: "24px 16px", position: "sticky", top: 0, height: "100vh" },
  sidebarLogo: { display: "flex", alignItems: "center", gap: "10px", padding: "8px 12px", marginBottom: "32px" },
  sideLogoIcon: { width: "38px", height: "38px", borderRadius: "10px", background: "var(--bg-card)", border: "1px solid var(--border)", display: "flex", alignItems: "center", justifyContent: "center" },
  sideLogoText: { fontSize: "22px", fontWeight: "800", letterSpacing: "-0.5px" },
  nav: { display: "flex", flexDirection: "column", gap: "6px", flex: 1 },
  navBtn: { display: "flex", alignItems: "center", gap: "12px", padding: "12px 14px", borderRadius: "var(--radius-sm)", background: "transparent", border: "none", cursor: "pointer", color: "var(--text-secondary)", fontFamily: "Sora, sans-serif", fontSize: "14px", fontWeight: "500", transition: "all 0.2s ease", position: "relative", textAlign: "left", width: "100%" },
  navBtnActive: { background: "rgba(79,142,247,0.1)", color: "var(--accent-primary)", fontWeight: "600" },
  navIcon: { fontSize: "18px", width: "24px", textAlign: "center" },
  navLabel: { flex: 1 },
  navIndicator: { width: "6px", height: "6px", borderRadius: "50%", background: "var(--accent-primary)" },
  sidebarBottom: { display: "flex", flexDirection: "column", gap: "12px" },
  activeBook: { display: "flex", alignItems: "center", gap: "10px", padding: "12px", background: "rgba(79,142,247,0.08)", borderRadius: "var(--radius-sm)", border: "1px solid rgba(79,142,247,0.2)" },
  activeBookIcon: { fontSize: "20px" },
  activeBookName: { fontSize: "12px", fontWeight: "600", color: "var(--text-primary)", maxWidth: "140px", overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" },
  activeBookSub: { fontSize: "10px", color: "var(--accent-primary)", marginTop: "2px" },
  userCard: { display: "flex", alignItems: "center", gap: "10px", padding: "12px", background: "var(--bg-card)", borderRadius: "var(--radius-sm)", border: "1px solid var(--border)" },
  userAvatar: { width: "34px", height: "34px", borderRadius: "50%", background: "linear-gradient(135deg, #4f8ef7, #7c3aed)", display: "flex", alignItems: "center", justifyContent: "center", fontSize: "14px", fontWeight: "700", flexShrink: 0 },
  userInfo: { flex: 1, minWidth: 0 },
  userName: { fontSize: "12px", fontWeight: "600", color: "var(--text-primary)", overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" },
  userRole: { fontSize: "10px", color: "var(--text-secondary)", marginTop: "1px" },
  logoutBtn: { background: "none", border: "none", cursor: "pointer", fontSize: "16px", color: "var(--text-muted)", padding: "4px" },
  main: { flex: 1, overflow: "auto", display: "flex", flexDirection: "column" },
  content: { padding: "40px", maxWidth: "900px", width: "100%" },
  pageHeader: { marginBottom: "32px" },
  pageTitle: { fontSize: "28px", fontWeight: "700", marginBottom: "6px" },
  pageSub: { fontSize: "14px", color: "var(--text-secondary)" },
  dropzone: { border: "2px dashed var(--border)", borderRadius: "var(--radius)", padding: "60px 40px", textAlign: "center", cursor: "pointer", transition: "all 0.3s ease", background: "var(--bg-card)", marginBottom: "24px" },
  dropzoneActive: { borderColor: "var(--accent-primary)", background: "rgba(79,142,247,0.05)", boxShadow: "var(--shadow-glow)" },
  dropzoneContent: { display: "flex", flexDirection: "column", alignItems: "center", gap: "12px" },
  dropzoneIcon: { fontSize: "48px", marginBottom: "8px" },
  dropzoneTitle: { fontSize: "20px", fontWeight: "600" },
  dropzoneSub: { fontSize: "14px", color: "var(--text-secondary)" },
  dropzoneHint: { display: "flex", gap: "10px", marginTop: "8px", flexWrap: "wrap", justifyContent: "center" },
  uploadingState: { display: "flex", flexDirection: "column", alignItems: "center", gap: "16px" },
  progressRing: { position: "relative", width: "80px", height: "80px" },
  progressText: { position: "absolute", top: "50%", left: "50%", transform: "translate(-50%, -50%)", fontSize: "14px", fontWeight: "700", color: "var(--accent-primary)" },
  uploadingText: { fontSize: "16px", fontWeight: "600" },
  uploadingSubText: { fontSize: "13px", color: "var(--text-secondary)" },
  infoGrid: { display: "grid", gridTemplateColumns: "repeat(3, 1fr)", gap: "16px" },
  infoCard: { textAlign: "center", padding: "24px 20px" },
  infoIcon: { fontSize: "28px", marginBottom: "12px" },
  infoTitle: { fontSize: "14px", fontWeight: "600", marginBottom: "8px" },
  infoDesc: { fontSize: "12px", color: "var(--text-secondary)", lineHeight: "1.5" },
  chatLayout: { display: "flex", flexDirection: "column", height: "100vh", padding: "0" },
  chatHeader: { display: "flex", alignItems: "center", justifyContent: "space-between", padding: "24px 32px", borderBottom: "1px solid var(--border)", background: "var(--bg-secondary)" },
  chatTitle: { fontSize: "20px", fontWeight: "700" },
  chatSub: { fontSize: "13px", color: "var(--text-secondary)", marginTop: "2px" },
  chatBadges: { display: "flex", gap: "8px" },
  chatMessages: { flex: 1, overflowY: "auto", padding: "24px 32px", display: "flex", flexDirection: "column", gap: "20px" },
  emptyChat: { display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", flex: 1, gap: "12px", opacity: 0.5, marginTop: "80px" },
  emptyChatIcon: { fontSize: "48px" },
  emptyChatTitle: { fontSize: "18px", fontWeight: "600" },
  emptyChatSub: { fontSize: "14px", color: "var(--text-secondary)" },
  msgWrap: { display: "flex", alignItems: "flex-start", gap: "12px" },
  msgWrapUser: { flexDirection: "row-reverse" },
  msgAvatar: { width: "36px", height: "36px", borderRadius: "50%", background: "var(--bg-card)", border: "1px solid var(--border)", display: "flex", alignItems: "center", justifyContent: "center", fontSize: "16px", flexShrink: 0 },
  msgAvatarUser: { width: "36px", height: "36px", borderRadius: "50%", background: "linear-gradient(135deg, #4f8ef7, #7c3aed)", display: "flex", alignItems: "center", justifyContent: "center", fontSize: "14px", fontWeight: "700", flexShrink: 0, color: "white" },
  msgBubble: { padding: "14px 18px", borderRadius: "16px", lineHeight: "1.6" },
  msgBubbleBot: { background: "var(--bg-card)", border: "1px solid var(--border)", borderTopLeftRadius: "4px" },
  msgBubbleUser: { background: "linear-gradient(135deg, #4f8ef7, #7c3aed)", borderTopRightRadius: "4px" },
  msgText: { fontSize: "14px", margin: 0 },
  msgTime: { fontSize: "10px", color: "var(--text-muted)", marginTop: "4px", paddingLeft: "4px" },
  statsRow: { display: "flex", gap: "6px", marginTop: "6px", flexWrap: "wrap" },
  statChip: { fontSize: "10px", padding: "3px 8px", background: "rgba(79,142,247,0.1)", border: "1px solid rgba(79,142,247,0.2)", borderRadius: "20px", color: "var(--accent-primary)" },
  typingBubble: { padding: "16px 20px", background: "var(--bg-card)", border: "1px solid var(--border)", borderRadius: "16px", borderTopLeftRadius: "4px", display: "flex", gap: "6px", alignItems: "center" },
  dot: { width: "8px", height: "8px", borderRadius: "50%", background: "var(--accent-primary)", animation: "pulse-glow 1.2s ease infinite", display: "block" },
  inputArea: { padding: "20px 32px", borderTop: "1px solid var(--border)", background: "var(--bg-secondary)", display: "flex", gap: "12px" },
  chatInput: { flex: 1, borderRadius: "var(--radius-sm)" },
  sendBtn: { padding: "14px 24px", flexShrink: 0 },
  statsGrid: { display: "grid", gridTemplateColumns: "repeat(4, 1fr)", gap: "16px", marginBottom: "24px" },
  statCard: { textAlign: "center", padding: "28px 20px" },
  statIcon: { fontSize: "28px", marginBottom: "12px" },
  statValue: { fontSize: "28px", fontWeight: "800", marginBottom: "6px", fontFamily: "JetBrains Mono, monospace" },
  statLabel: { fontSize: "12px", color: "var(--text-secondary)" },
  comparisonCard: { padding: "28px" },
  compTitle: { fontSize: "18px", fontWeight: "700", marginBottom: "24px" },
  compGrid: { display: "grid", gridTemplateColumns: "1fr auto 1fr", gap: "24px", alignItems: "start" },
